"use client";

import React, { useState, useMemo, useEffect } from "react";
import { 
  ChevronLeft, ChevronRight, Plus, Trash2, Copy, 
  Check, Save, Wand2, Calendar, Lock, Palmtree, 
  AlertTriangle, X, History, Clock, ChevronDown
} from "lucide-react";

/* ---------------- 1. CONFIGURATION ---------------- */
const HOLIDAYS = ["2026-01-26"]; 
const APPROVED_LEAVES = ["2026-01-27"]; 

const PROJECTS = [
    { id: "p1", name: "Internal / Admin", code: "INT-001", color: "bg-slate-500", billable: false },
    { id: "p2", name: "Acme Corp: Redesign", code: "ACM-102", color: "bg-blue-600", billable: true },
    { id: "p3", name: "Globex: Mobile App", code: "GLO-404", color: "bg-indigo-600", billable: true },
    { id: "p4", name: "Stark Ind: Consulting", code: "STK-999", color: "bg-amber-600", billable: true },
];

/* ---------------- 2. TYPES ---------------- */
type Status = "DRAFT" | "SUBMITTED" | "APPROVED";

interface DayEntry {
    id: string;
    projectId: string;
    hours: number;   // 0 - 23
    minutes: number; // 0 - 59
    notes: string;
}

interface WeekData {
    status: Status;
    entries: Record<string, DayEntry[]>;
}

type TimesheetDB = Record<string, WeekData>;

/* ---------------- 3. HELPERS ---------------- */
const formatDate = (d: Date) => d.toISOString().split("T")[0];

const addDays = (d: Date, days: number) => {
    const nd = new Date(d);
    nd.setDate(nd.getDate() + days);
    return nd;
};

const startOfWeek = (date: Date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    d.setHours(0, 0, 0, 0);
    return d;
};

// Convert Hours + Minutes to Decimal for stats calculation (e.g. 1h 30m = 1.5)
const toDecimal = (h: number, m: number) => h + (m / 60);

// Format for display (e.g., "1h 30m" or "45m")
const formatDuration = (h: number, m: number) => {
    if (h === 0 && m === 0) return "0h";
    if (h > 0 && m > 0) return `${h}h ${m}m`;
    if (h > 0) return `${h}h`;
    return `${m}m`;
};

/* ---------------- 4. MAIN COMPONENT ---------------- */
export default function PrecisionTimesheet() {
    // State
    const [currentWeekStart, setCurrentWeekStart] = useState<Date>(startOfWeek(new Date("2026-01-26")));
    const [db, setDb] = useState<TimesheetDB>({
        "2026-01-26": { status: "DRAFT", entries: {} }
    });

    // UI State
    const [selectedDate, setSelectedDate] = useState<string | null>(null); 
    const [isCopyMenuOpen, setIsCopyMenuOpen] = useState(false);
    const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
    const [toast, setToast] = useState<{ type: 'success' | 'error', msg: string } | null>(null);

    // Helpers
    const currentWeekKey = formatDate(currentWeekStart);
    const currentData = db[currentWeekKey] || { status: "DRAFT", entries: {} };
    const isLocked = currentData.status !== "DRAFT";

    // Auto-dismiss toast
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    /* --- DERIVED: DAYS --- */
    const days = useMemo(() => {
        return Array.from({ length: 7 }).map((_, i) => {
            const d = addDays(currentWeekStart, i);
            const dateStr = formatDate(d);
            const isBlocked = HOLIDAYS.includes(dateStr) || APPROVED_LEAVES.includes(dateStr);

            return {
                label: d.toLocaleDateString("en-US", { weekday: "short" }),
                date: dateStr,
                dayNum: d.getDate(),
                isWeekend: i === 5 || i === 6,
                isBlocked,
                isHoliday: HOLIDAYS.includes(dateStr),
                isLeave: APPROVED_LEAVES.includes(dateStr),
                entries: currentData.entries[dateStr] || []
            };
        });
    }, [currentWeekStart, currentData]);

    /* --- DERIVED: STATS --- */
    const stats = useMemo(() => {
        let totalDec = 0;
        let billableDec = 0;
        
        Object.values(currentData.entries).forEach(dayEntries => {
            dayEntries.forEach(e => {
                const decimal = toDecimal(e.hours, e.minutes);
                totalDec += decimal;
                if (PROJECTS.find(p => p.id === e.projectId)?.billable) billableDec += decimal;
            });
        });
        
        return { 
            total: totalDec.toFixed(1), // Display as 1 decimal place
            billable: billableDec.toFixed(1), 
            utilization: Math.min(100, (totalDec / 40) * 100) 
        };
    }, [currentData]);

    /* --- ACTIONS --- */
    const updateDb = (fn: (prev: TimesheetDB) => TimesheetDB) => setDb(prev => fn(prev));

    const handleNavigate = (dir: 'prev' | 'next') => {
        setCurrentWeekStart(prev => addDays(prev, dir === 'next' ? 7 : -7));
    };

    const handleSmartFill = () => {
        if (isLocked) return;
        const newEntries = { ...currentData.entries };
        let count = 0;

        days.slice(0, 5).forEach(d => {
            if (d.isBlocked) return;
            if (!newEntries[d.date] || newEntries[d.date].length === 0) {
                newEntries[d.date] = [{
                    id: crypto.randomUUID(),
                    projectId: PROJECTS[0].id,
                    hours: 8,
                    minutes: 0,
                    notes: "Standard Hours"
                }];
                count++;
            }
        });

        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, entries: newEntries }
        }));
        setToast({ type: 'success', msg: `Auto-filled ${count} days` });
    };

    const handleCopyWeek = (targetDateStr: string) => {
        if (isLocked) return;
        const sourceEntries = db[targetDateStr]?.entries || {};
        const newEntries: Record<string, DayEntry[]> = {};
        
        days.forEach((day, index) => {
            if (day.isBlocked) return;
            const sourceDate = addDays(new Date(targetDateStr), index);
            const sourceDayEntries = sourceEntries[formatDate(sourceDate)] || [];

            if (sourceDayEntries.length > 0) {
                newEntries[day.date] = sourceDayEntries.map(e => ({ ...e, id: crypto.randomUUID() }));
            }
        });

        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, entries: newEntries }
        }));
        setToast({ type: 'success', msg: "Imported entries successfully" });
        setIsCopyMenuOpen(false);
    };

    const handleSubmit = () => {
        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, status: "SUBMITTED" }
        }));
        setIsSubmitModalOpen(false);
        setToast({ type: 'success', msg: "Timesheet Submitted!" });
    };

    const handleWithdraw = () => {
        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, status: "DRAFT" }
        }));
        setToast({ type: 'success', msg: "Withdrawn to Draft" });
    };

    /* --- SIDE PANEL ACTIONS --- */
    const addEntry = (date: string) => {
        const newEntry = { id: crypto.randomUUID(), projectId: PROJECTS[0].id, hours: 0, minutes: 0, notes: "" };
        updateDb(prev => {
            const week = prev[currentWeekKey] || { status: 'DRAFT', entries: {} };
            return {
                ...prev,
                [currentWeekKey]: {
                    ...week,
                    entries: { ...week.entries, [date]: [...(week.entries[date] || []), newEntry] }
                }
            };
        });
    };

    // STRICT VALIDATION UPDATE
    const updateEntry = (date: string, id: string, field: keyof DayEntry, val: any) => {
        let cleanVal = val;

        // Validation for numbers
        if (field === 'hours') {
            cleanVal = Math.max(0, parseInt(val) || 0); // No negatives
        }
        if (field === 'minutes') {
            cleanVal = Math.max(0, Math.min(59, parseInt(val) || 0)); // 0 to 59
        }

        updateDb(prev => {
            const week = prev[currentWeekKey];
            const updated = week.entries[date].map(e => e.id === id ? { ...e, [field]: cleanVal } : e);
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: updated } } };
        });
    };

    const deleteEntry = (date: string, id: string) => {
        updateDb(prev => {
            const week = prev[currentWeekKey];
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: week.entries[date].filter(e => e.id !== id) } } };
        });
    };

    return (
        <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#0B0F19] text-slate-900 dark:text-slate-100 font-sans pb-20">
            
            {/* 1. HEADER */}
            <div className="bg-white dark:bg-[#11151F] border-b border-slate-200 dark:border-slate-800 px-6 py-4 sticky top-0 z-30">
                <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-600 text-white rounded-lg"><Clock size={20} /></div>
                        <div>
                            <h1 className="text-lg font-bold leading-none">Timesheet Portal</h1>
                            <p className="text-xs text-slate-500 mt-1 font-medium">Weekly Entry</p>
                        </div>
                    </div>

                    {/* Stats Pill */}
                    <div className="hidden md:flex items-center gap-6 bg-slate-50 dark:bg-slate-900 px-6 py-2 rounded-full border border-slate-200 dark:border-slate-800">
                        <div className="text-center">
                            <span className="text-[10px] font-black uppercase text-slate-400 block">Total</span>
                            <span className="text-sm font-black text-slate-900 dark:text-white">{stats.total}h</span>
                        </div>
                        <div className="w-[1px] h-6 bg-slate-200 dark:bg-slate-700" />
                        <div className="text-center">
                            <span className="text-[10px] font-black uppercase text-slate-400 block">Billable</span>
                            <span className="text-sm font-black text-emerald-500">{stats.billable}h</span>
                        </div>
                        <div className="w-[1px] h-6 bg-slate-200 dark:bg-slate-700" />
                         <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${currentData.status === 'DRAFT' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                            {currentData.status}
                        </div>
                    </div>

                    {/* Navigation */}
                    <div className="flex items-center bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                        <button onClick={() => handleNavigate('prev')} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-md shadow-sm transition-all"><ChevronLeft size={16}/></button>
                        <div className="px-4 text-xs font-bold tabular-nums">
                            {days[0].date} <span className="text-slate-400 mx-1">—</span> {days[6].date}
                        </div>
                        <button onClick={() => handleNavigate('next')} className="p-2 hover:bg-white dark:hover:bg-slate-700 rounded-md shadow-sm transition-all"><ChevronRight size={16}/></button>
                    </div>
                </div>
            </div>

            {/* 2. TOOLBAR */}
            <div className="max-w-7xl mx-auto px-6 py-6">
                <div className="flex justify-end gap-3 mb-6">
                    {/* IMPORT MENU */}
                    <div className="relative">
                        <button 
                            onClick={() => setIsCopyMenuOpen(!isCopyMenuOpen)}
                            disabled={isLocked}
                            className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg text-xs font-bold text-slate-600 dark:text-slate-300 hover:border-blue-500 transition-all shadow-sm disabled:opacity-50"
                        >
                            <History size={16} className="text-blue-500" /> Import Previous <ChevronDown size={14} />
                        </button>
                        
                        {isCopyMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-64 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                                <div className="p-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                                    <span className="text-[10px] font-black uppercase text-slate-400">Past 3 Months</span>
                                </div>
                                <div className="max-h-60 overflow-y-auto">
                                    {Array.from({ length: 12 }).map((_, i) => {
                                        const d = addDays(currentWeekStart, -(i + 1) * 7);
                                        const dStr = formatDate(d);
                                        return (
                                            <button 
                                                key={i}
                                                onClick={() => handleCopyWeek(dStr)}
                                                className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-medium border-b border-slate-50 dark:border-slate-800/50 last:border-0"
                                            >
                                                <div className="font-bold text-slate-700 dark:text-slate-200">Week of {d.toLocaleDateString()}</div>
                                                <div className="text-[10px] text-slate-400 mt-0.5">Click to import template</div>
                                            </button>
                                        )
                                    })}
                                </div>
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={handleSmartFill}
                        disabled={isLocked}
                        className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-lg text-xs font-bold text-slate-600 dark:text-slate-300 hover:border-purple-500 transition-all shadow-sm disabled:opacity-50"
                    >
                        <Wand2 size={16} className="text-purple-500" /> Smart Fill
                    </button>
                </div>

                {/* 3. GRID */}
                <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
                    {days.map((d) => {
                        // Calculate total day duration
                        const totalDayMinutes = d.entries.reduce((a, b) => a + (b.hours * 60) + b.minutes, 0);
                        const displayHours = Math.floor(totalDayMinutes / 60);
                        const displayMinutes = totalDayMinutes % 60;
                        const hasHours = totalDayMinutes > 0;
                        const isComplete = totalDayMinutes >= 480; // 8 hours * 60
                        
                        return (
                            <div 
                                key={d.date}
                                onClick={() => !d.isBlocked && !isLocked && setSelectedDate(d.date)}
                                className={`
                                    relative min-h-[220px] rounded-2xl border transition-all duration-300 flex flex-col group
                                    ${d.isBlocked 
                                        ? "bg-slate-50 dark:bg-slate-900/50 border-slate-200 dark:border-slate-800 cursor-not-allowed" 
                                        : "bg-white dark:bg-[#11151F] border-slate-200 dark:border-slate-800 hover:border-blue-400 hover:shadow-lg cursor-pointer"
                                    }
                                `}
                            >
                                {/* Header */}
                                <div className="p-4 border-b border-slate-100 dark:border-slate-800/50 flex justify-between items-center">
                                    <div>
                                        <div className="text-[10px] font-black uppercase text-slate-400">{d.label}</div>
                                        <div className={`text-xl font-black ${d.isBlocked ? 'text-slate-300' : 'text-slate-800 dark:text-white'}`}>{d.dayNum}</div>
                                    </div>
                                    {d.isHoliday && <Lock size={16} className="text-purple-400" />}
                                    {d.isLeave && <Palmtree size={16} className="text-amber-400" />}
                                    
                                    {!d.isBlocked && hasHours && (
                                        <span className={`text-[10px] font-black px-2 py-0.5 rounded ${isComplete ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>
                                            {formatDuration(displayHours, displayMinutes)}
                                        </span>
                                    )}
                                </div>

                                {/* Body */}
                                <div className="flex-1 p-2 space-y-2">
                                    {d.entries.map(e => {
                                        const proj = PROJECTS.find(p => p.id === e.projectId);
                                        return (
                                            <div key={e.id} className="p-2 bg-slate-50 dark:bg-slate-900 rounded-lg border border-slate-100 dark:border-slate-800">
                                                <div className="flex justify-between mb-1">
                                                    <div className={`w-1.5 h-1.5 rounded-full ${proj?.color}`} />
                                                    <span className="text-[10px] font-bold">{formatDuration(e.hours, e.minutes)}</span>
                                                </div>
                                                <p className="text-[10px] text-slate-500 font-medium truncate">{proj?.code}</p>
                                            </div>
                                        )
                                    })}
                                    
                                    {/* Empty State / Add CTA */}
                                    {!d.isBlocked && d.entries.length === 0 && (
                                        <div className="h-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-500 flex items-center justify-center">
                                                <Plus size={16} />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* 4. FOOTER */}
            <div className="fixed bottom-0 w-full bg-white dark:bg-[#11151F] border-t border-slate-200 dark:border-slate-800 p-4 z-40 flex justify-center">
                {isLocked ? (
                    <button onClick={handleWithdraw} className="bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-8 py-3 rounded-full font-bold text-sm hover:bg-slate-300 dark:hover:bg-slate-700 transition-colors flex items-center gap-2">
                         <Lock size={16} /> Submitted - Click to Withdraw
                    </button>
                ) : (
                    <button 
                        onClick={() => setIsSubmitModalOpen(true)} 
                        disabled={stats.total === "0.0"}
                        className="bg-blue-600 text-white px-8 py-3 rounded-full font-bold text-sm hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/30 disabled:opacity-50 disabled:shadow-none flex items-center gap-2"
                    >
                        <Save size={18} /> Submit {stats.total} Hours
                    </button>
                )}
            </div>

            {/* --- SLIDE-OVER DRAWER --- */}
            {selectedDate && (
                <div className="fixed inset-0 z-50 flex justify-end">
                    <div className="absolute inset-0 bg-slate-900/30 backdrop-blur-sm" onClick={() => setSelectedDate(null)} />
                    <div className="relative w-full max-w-md bg-white dark:bg-[#11151F] h-full shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <div>
                                <h2 className="text-xl font-black text-slate-900 dark:text-white">
                                    {new Date(selectedDate).toLocaleDateString("en-US", { weekday: 'long' })}
                                </h2>
                                <p className="text-sm font-medium text-slate-500">{selectedDate}</p>
                            </div>
                            <button onClick={() => setSelectedDate(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors">
                                <X size={20} className="text-slate-500" />
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            <div className="space-y-4">
                                {(currentData.entries[selectedDate] || []).map((e, idx) => (
                                    <div key={e.id} className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-4 shadow-sm hover:border-blue-400 transition-colors relative">
                                        
                                        <div className="flex gap-3 mb-4">
                                            <div className="flex-1">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Project</label>
                                                <select 
                                                    value={e.projectId} 
                                                    onChange={(ev) => updateEntry(selectedDate, e.id, 'projectId', ev.target.value)}
                                                    className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none"
                                                >
                                                    {PROJECTS.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                                </select>
                                            </div>
                                            
                                            {/* SPLIT HOURS / MINUTES INPUTS */}
                                            <div className="w-16">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Hrs</label>
                                                <input 
                                                    type="number" min="0" max="23"
                                                    value={e.hours} 
                                                    onChange={(ev) => updateEntry(selectedDate, e.id, 'hours', ev.target.value)}
                                                    className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none"
                                                />
                                            </div>
                                            <div className="w-16">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Mins</label>
                                                <input 
                                                    type="number" min="0" max="59"
                                                    value={e.minutes} 
                                                    onChange={(ev) => updateEntry(selectedDate, e.id, 'minutes', ev.target.value)}
                                                    className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none"
                                                />
                                            </div>
                                        </div>
                                        
                                        <input 
                                            type="text" 
                                            placeholder="What did you work on?" 
                                            value={e.notes}
                                            onChange={(ev) => updateEntry(selectedDate, e.id, 'notes', ev.target.value)}
                                            className="w-full text-sm bg-slate-50 dark:bg-slate-800 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500/20"
                                        />

                                        <button 
                                            onClick={() => deleteEntry(selectedDate, e.id)}
                                            className="absolute -top-2 -right-2 bg-white dark:bg-slate-800 text-slate-400 hover:text-red-500 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <button 
                                onClick={() => addEntry(selectedDate)}
                                className="w-full py-4 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl flex items-center justify-center gap-2 text-slate-500 font-bold hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-slate-800 transition-all"
                            >
                                <Plus size={20} /> Add Activity
                            </button>
                        </div>
                        
                        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900">
                             <button onClick={() => setSelectedDate(null)} className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-colors">
                                 Done
                             </button>
                        </div>
                    </div>
                </div>
            )}

            {/* TOAST */}
            {toast && (
                <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full font-bold shadow-xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 z-50 ${
                    toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'
                }`}>
                    {toast.type === 'success' ? <Check size={18} /> : <AlertTriangle size={18} />}
                    {toast.msg}
                </div>
            )}

            {/* SUBMIT MODAL */}
            {isSubmitModalOpen && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
                    <div className="bg-white dark:bg-slate-900 rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl animate-in zoom-in-95">
                        <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Lock size={32} />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Confirm Submission</h3>
                        <p className="text-sm text-slate-500 mb-6">This will lock the week of <strong>{currentWeekKey}</strong>. You cannot edit entries after this.</p>
                        <div className="flex gap-3 justify-center">
                            <button onClick={() => setIsSubmitModalOpen(false)} className="px-5 py-2 rounded-lg font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">Cancel</button>
                            <button onClick={handleSubmit} className="px-6 py-2 rounded-lg font-bold bg-blue-600 text-white hover:bg-blue-700">Confirm</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}